create table citizen (
	village_id INT REFERENCES village(village_id),
	citizen_id SERIAL UNIQUE,
	password_hash VARCHAR(255) not null,
	aadhar VARCHAR(12) PRIMARY KEY,
	gender VARCHAR(6),
	name VARCHAR(25) not null,
	email VARCHAR(50),
	image VARCHAR(300),
	household_id INT REFERENCES household(household_id),
	dob DATE,
	education_qualification VARCHAR(50),
	phone VARCHAR(10)
);


